const emptyClient: ClientLegalData = { legalName: "", legalForm: "", registrationCountry: "PL", registeredAddress: "", postalCode: "", city: "", billingAddressDifferent: false, billingAddress: "", billingPostalCode: "", billingCity: "", billingCountry: "PL", taxId: "", companyNumber: "", entityType: "PL_KRS", registryName: "Krajowy Rejestr Sądowy", representativeName: "", representativePosition: "", representativeAuthorityBasis: "", businessEmail: "", phone: "", brandName: "", domain: "", appName: "", communicationLanguage: "pl", authorityConfirmed: false, companyDataConfirmed: false };

async function api(path: string, options: RequestInit = {}): Promise<ApiResult> {
  const response = await fetch(path, { credentials: "same-origin", ...options, headers: { "content-type": "application/json", ...(options.headers ?? {}) } });
  const payload = await response.json() as ApiResult; if (!response.ok || !payload.ok) throw new Error(payload.message || payload.code || "Request failed"); return payload;
}

function money(minor: number | null | undefined, currency: string, locale: Locale) { return new Intl.NumberFormat(locale, { style: "currency", currency }).format((minor ?? 0) / 100); }
function wholeMoney(minor: number, currency: string, locale: Locale) { return new Intl.NumberFormat(locale, { style: "currency", currency, maximumFractionDigits: 0 }).format(minor / 100); }

function Field({ label, name, value, onChange, type = "text", required = true, autoComplete, readOnly = false }: { label: string; name: keyof ClientLegalData; value: string; onChange: (name: keyof ClientLegalData, value: string) => void; type?: string; required?: boolean; autoComplete?: string; readOnly?: boolean }) {
  return <label className="contract-field"><span>{label}{required ? " *" : ""}</span><input name={String(name)} type={type} value={value} required={required} readOnly={readOnly} autoComplete={autoComplete} onChange={(event) => onChange(name, event.target.value)} /></label>;
}

function Summary({ quote, catalog, locale, selection }: { quote: CommerceQuote | null; catalog: CommerceCatalog | null; locale: Locale; selection: OrderSelection }) {
  const t = copy[locale]; const currency = quote?.currency ?? catalog?.market.currency ?? currencyForMarket(selection.market);
  return <div className="contract-summary-card"><p className="eyebrow">{t.summary}</p><h2>{quote ? money(quote.dueTodayNetMinor, currency, locale) : "—"}</h2><dl><div><dt>{t.country}</dt><dd>{selection.registrationCountry}</dd></div><div><dt>{t.language}</dt><dd>{locale.toUpperCase()}</dd></div><div><dt>{t.currency}</dt><dd>{currency}</dd></div><div><dt>{t.term}</dt><dd>{selection.contractTerm === "ANNUAL_12" ? t.annual : t.open}</dd></div><div><dt>{t.startDate}</dt><dd>{t.startAfterPayment}</dd></div><div><dt>{t.monthly}</dt><dd>{money(quote?.monthlyNetMinor, currency, locale)}</dd></div><div><dt>{t.oneTime}</dt><dd>{money(quote?.oneTimeNetMinor, currency, locale)}</dd></div><div><dt>{t.activation}</dt><dd>{money(quote?.activationFeeMinor, currency, locale)}</dd></div><div><dt>{t.tax}</dt><dd>{t.taxPending}</dd></div><div><dt>{t.nextCharge}</dt><dd>{t.nextChargeStripe}</dd></div><div><dt>{t.implementation}</dt><dd>{quote ? `≈ ${quote.deploymentDays} ${t.businessDays}` : "—"}</dd></div></dl>{quote?.contractTerm === "ANNUAL_12" ? <p className="summary-commitment"><b>{t.annualValue}</b><span>{money(quote.annualCommitmentNetMinor, currency, locale)}</span></p> : null}<p className="summary-note">{t.recurringNote}</p></div>;
}

function verificationStatusLabel(status: string | null | undefined, locale: Locale): string {
  const labels: Record<Locale, Record<string, string>> = {
    pl: { NOT_STARTED: "Nie rozpoczęto", FETCHING: "Pobieranie danych", COMPANY_VERIFIED: "Firma zweryfikowana", EMAIL_VERIFICATION_REQUIRED: "Wymagane potwierdzenie e-maila", EMAIL_VERIFIED: "E-mail potwierdzony", REPRESENTATION_CHECK_REQUIRED: "Wymagane sprawdzenie reprezentacji", SECOND_SIGNER_REQUIRED: "Wymagany drugi podpisujący", POWER_OF_ATTORNEY_REQUIRED: "Wymagane pełnomocnictwo", MANUAL_REVIEW_REQUIRED: "Wymagana ręczna weryfikacja", VERIFIED: "Zweryfikowano", REJECTED: "Odrzucono", REGISTRY_UNAVAILABLE: "Rejestr chwilowo niedostępny" },
    en: { NOT_STARTED: "Not started", FETCHING: "Fetching registry data", COMPANY_VERIFIED: "Company verified", EMAIL_VERIFICATION_REQUIRED: "Email verification required", EMAIL_VERIFIED: "Email verified", REPRESENTATION_CHECK_REQUIRED: "Representation check required", SECOND_SIGNER_REQUIRED: "Second signer required", POWER_OF_ATTORNEY_REQUIRED: "Power of attorney required", MANUAL_REVIEW_REQUIRED: "Manual review required", VERIFIED: "Verified", REJECTED: "Rejected", REGISTRY_UNAVAILABLE: "Registry temporarily unavailable" },
    es: { NOT_STARTED: "No iniciado", FETCHING: "Consultando el registro", COMPANY_VERIFIED: "Empresa verificada", EMAIL_VERIFICATION_REQUIRED: "Verificación de correo requerida", EMAIL_VERIFIED: "Correo verificado", REPRESENTATION_CHECK_REQUIRED: "Se requiere revisar la representación", SECOND_SIGNER_REQUIRED: "Se requiere un segundo firmante", POWER_OF_ATTORNEY_REQUIRED: "Se requiere poder de representación", MANUAL_REVIEW_REQUIRED: "Se requiere revisión manual", VERIFIED: "Verificado", REJECTED: "Rechazado", REGISTRY_UNAVAILABLE: "Registro temporalmente no disponible" },
  };
  return status ? labels[locale][status] ?? status : labels[locale].NOT_STARTED;
}

export function ContractFlow({ initialLocale }: { initialLocale: Locale }) {
  const initialCountry = initialLocale === "pl" ? "PL" : initialLocale === "es" ? "ES" : "GB";
  const started = useRef(false); const [phase, setPhase] = useState(0); const [csrf, setCsrf] = useState(""); const [busy, setBusy] = useState(false); const [error, setError] = useState("");
  const [order, setOrder] = useState<OrderView | null>(null); const [catalog, setCatalog] = useState<CommerceCatalog | null>(null); const [quote, setQuote] = useState<CommerceQuote | null>(null); const [marketConfirmed, setMarketConfirmed] = useState(false);
  const [selection, setSelection] = useState<OrderSelection>({ market: marketForBillingCountry(initialCountry), language: initialLocale, contractTerm: "ANNUAL_12", registrationCountry: initialCountry, billingCountry: initialCountry, planId: null, addons: [] });
  const [client, setClient] = useState<ClientLegalData>({ ...emptyClient, registrationCountry: selection.registrationCountry, billingCountry: selection.billingCountry, communicationLanguage: selection.language });
  const [acceptance, setAcceptance] = useState({ companyData: false, agreementAndTerms: false, dataProcessing: false, authority: false, annualCommitment: false, recurringPayment: false });
  const [verification, setVerification] = useState<CompanyVerificationView | null>(null); const [otpCode, setOtpCode] = useState(""); const [debugOtp, setDebugOtp] = useState("");
  const [secondSigner, setSecondSigner] = useState({ name: "", position: "", authorityBasis: "", email: "" }); const [debugSignerLink, setDebugSignerLink] = useState(""); const [verificationNotice, setVerificationNotice] = useState("");
  const locale = selection.language; const t = copy[locale]; const foreignIdentifier = foreignIdentifierForCountry(selection.registrationCountry); const selectedCurrency = currencyForMarket(selection.market);
  const openActivationFeeMinor = catalog?.market.code === selection.market ? catalog.market.activationFeeOpenMinor : selection.market === "PL" ? 39_900 : 9_900;

  const loadCatalog = useCallback(async (scope: OrderSelection) => {
    const result = await api(`/api/commerce/catalog?market=${scope.market}&language=${scope.language}`); setCatalog(result.catalog as CommerceCatalog);
  }, []);

  useEffect(() => {
    void (async () => {
      try {
        const bootstrap = await api("/api/commerce/bootstrap"); setCsrf(bootstrap.csrfToken as string); setOrder(bootstrap.order as OrderView);
        const current = await api("/api/commerce/draft"); const saved = current.selection as Partial<OrderSelection>;
        if (saved.market && saved.language && saved.contractTerm && saved.registrationCountry && saved.billingCountry) {
          const restoredMarketCode = marketForBillingCountry(saved.registrationCountry);
          const restoredMarket = selectionForMarket(saved as OrderSelection, restoredMarketCode, saved.language === "es" ? "ES" : "DE"); const restored = { ...restoredMarket, billingCountry: restoredMarket.registrationCountry };
          setSelection(restored); if (current.client) { const savedClient = current.client as ClientLegalData; const restoredEntityType: CompanyEntityType = restored.market === "PL" ? (savedClient.entityType === "FOREIGN" ? "PL_KRS" : savedClient.entityType) : "FOREIGN"; const entityTypeChanged = savedClient.entityType !== restoredEntityType; const restoredRegistryName = restoredEntityType === "PL_KRS" ? "Krajowy Rejestr Sądowy" : restoredEntityType === "PL_CEIDG" ? "CEIDG" : restoredEntityType === "FOREIGN" ? foreignIdentifierForCountry(restored.registrationCountry).registryName : savedClient.registryName; setClient({ ...savedClient, registrationCountry: restored.registrationCountry, billingCountry: restored.billingCountry, entityType: restoredEntityType, registryName: entityTypeChanged || !savedClient.registryName ? restoredRegistryName : savedClient.registryName, companyNumber: entityTypeChanged ? "" : savedClient.companyNumber, taxId: entityTypeChanged ? "" : savedClient.taxId, companyDataConfirmed: entityTypeChanged ? false : savedClient.companyDataConfirmed }); } setVerification((current.verification as CompanyVerificationView | null) ?? null); await loadCatalog(restored);
        } else await loadCatalog(selection);
        if (!started.current) { trackEvent("contract_flow_started"); started.current = true; }
      } catch (failure) { setError(failure instanceof Error ? failure.message : "Could not start the contract flow"); }
    })();
  // Initial bootstrap is intentionally performed once.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => { if (!csrf) return; const timeout = window.setTimeout(() => { void api("/api/commerce/selection", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ selection }) }).catch(() => undefined); }, 350); return () => window.clearTimeout(timeout); }, [selection, csrf]);
  useEffect(() => {
    const timeout = window.setTimeout(() => { if (!csrf || (!selection.planId && selection.addons.length === 0)) { setQuote(null); return; } void api("/api/commerce/quote", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ selection }) }).then((result) => setQuote(result.quote as CommerceQuote)).catch(() => setQuote(null)); }, 300);
    return () => window.clearTimeout(timeout);
  }, [selection, csrf]);
  useEffect(() => { if (phase !== 6 || verification?.status === "VERIFIED") return; const timer = window.setInterval(() => { void api("/api/company-verification").then((result) => setVerification((result.verification as CompanyVerificationView | null) ?? null)).catch(() => undefined); }, 5_000); return () => window.clearInterval(timer); }, [phase, verification?.status]);

  const changeSelection = <K extends keyof OrderSelection>(key: K, value: OrderSelection[K]) => {
    setError(""); setMarketConfirmed(key === "language" ? marketConfirmed : false); setAcceptance({ companyData: false, agreementAndTerms: false, dataProcessing: false, authority: false, annualCommitment: false, recurringPayment: false });
    const nextSelection = { ...selection, [key]: value } as OrderSelection;
    if (key === "planId") {
      const nextPlanId = value as string | null;
      nextSelection.addons = selection.addons.filter((chosen) => { const addon = catalog?.addons.find((item) => item.id === chosen.addonId); return Boolean(addon && (nextPlanId ? addon.compatiblePlanIds.length === 0 || addon.compatiblePlanIds.includes(nextPlanId) : addon.standalone)); });
    }
    setSelection(nextSelection);
    if ((key === "market" || key === "language") && csrf) void loadCatalog(nextSelection).catch((failure) => setError(failure instanceof Error ? failure.message : "Catalogue unavailable"));
    if (key === "market") trackEvent("market_selected", { market: value }); if (key === "language") trackEvent("language_selected", { document_language: value });
    if (key === "contractTerm") trackEvent("contract_term_selected", { contract_term: value }); if (key === "planId") trackEvent("plan_selected", { plan_id: value });
  };
  const selectCompanyCountry = (country: string) => {
    if (!companyCountries.some((item) => item.code === country)) return;
    const market = marketForBillingCountry(country); const countryChanged = selection.registrationCountry !== country;
    const nextSelection = { ...selection, market, registrationCountry: country, billingCountry: country };
    const identifier = foreignIdentifierForCountry(country);
    setSelection(nextSelection); setMarketConfirmed(false); setQuote(null); setVerification(null); setDebugOtp(""); setOtpCode(""); setError("");
    setClient((current) => ({ ...current, registrationCountry: country, billingCountry: country, entityType: country === "PL" ? "PL_KRS" : "FOREIGN", registryName: country === "PL" ? "Krajowy Rejestr Sądowy" : identifier.registryName, companyNumber: countryChanged ? "" : current.companyNumber, taxId: countryChanged ? "" : current.taxId, companyDataConfirmed: false }));
    if (csrf) void loadCatalog(nextSelection).catch((failure) => setError(failure instanceof Error ? failure.message : "Catalogue unavailable"));
    trackEvent("company_country_selected", { country, market });
  };
  const setClientField = (name: keyof ClientLegalData, value: string | boolean) => { const verificationSensitive = ["legalName","legalForm","registeredAddress","postalCode","city","taxId","companyNumber","registryName","representativeName","representativePosition","representativeAuthorityBasis","businessEmail"].includes(name); if (verificationSensitive) setVerification((current) => current ? { ...current, clientConfirmed: false } : current); setClient((current) => ({ ...current, [name]: value, ...(verificationSensitive ? { companyDataConfirmed: false } : {}) })); };
  const setForeignIdentifier = (value: string) => { setClientField("companyNumber", value); if (foreignIdentifier.taxBased) setClientField("taxId", value); };
  const selectedPlan = catalog?.plans.find((plan) => plan.id === selection.planId);
  const toggleAddon = (addonId: string, enabled: boolean) => { setSelection((current) => ({ ...current, addons: enabled ? [...current.addons, { addonId, quantity: 1 }] : current.addons.filter((item) => item.addonId !== addonId) })); trackEvent("addon_selected", { addon_id: addonId, selected: enabled }); };
  const setAddonQuantity = (addonId: string, quantity: number) => setSelection((current) => ({ ...current, addons: current.addons.map((item) => item.addonId === addonId ? { ...item, quantity } : item) }));

  const next = () => { setError(""); if (phase === 0 && !marketConfirmed) { setError(t.confirmMarket); return; } if (phase === 3 && !selection.planId && !catalog?.addons.some((addon) => addon.standalone)) { setError(t.plan); return; } if (phase === 4 && !selection.planId && selection.addons.length === 0) { setError(t.addons); return; } if (phase === 6 && verification?.status !== "VERIFIED") { setError(t.verificationBlocked); return; } setPhase((current) => current === 0 ? 2 : Math.min(8, current + 1)); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const selectEntityType = (entityType: CompanyEntityType) => { setVerification(null); setDebugOtp(""); setClient((current) => ({ ...current, entityType, registryName: entityType === "PL_KRS" ? "Krajowy Rejestr Sądowy" : entityType === "PL_CEIDG" ? "CEIDG" : "", companyNumber: "", taxId: "", companyDataConfirmed: false })); };
  const lookupCompany = async () => { setBusy(true); setError(""); try { const result = await api("/api/company-verification/lookup", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ entityType: client.entityType, country: selection.registrationCountry, registrationNumber: client.companyNumber, taxNumber: client.taxId, registryName: client.registryName, legalName: client.legalName, registeredAddress: client.registeredAddress, postalCode: client.postalCode, city: client.city, entityTypeName: client.legalForm }) }); const found = result.verification as CompanyVerificationView; setVerification(found); setClient((current) => ({ ...current, legalName: found.legalName || current.legalName, legalForm: found.entityTypeName || current.legalForm, registeredAddress: found.registeredAddress || current.registeredAddress, postalCode: found.postalCode || current.postalCode, city: found.city || current.city, taxId: found.taxNumber || current.taxId, companyNumber: found.registrationNumber || current.companyNumber, registryName: found.registryName || current.registryName, companyDataConfirmed: false })); } catch (failure) { setError(failure instanceof Error ? failure.message : "Company verification failed"); } finally { setBusy(false); } };
  const confirmVerifiedCompany = async () => { setBusy(true); setError(""); try { const result = await api("/api/company-verification/confirm", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ confirmed: client.companyDataConfirmed, representativeName: client.representativeName, representativePosition: client.representativePosition, representativeAuthorityBasis: client.representativeAuthorityBasis, businessEmail: client.businessEmail }) }); setVerification(result.verification as CompanyVerificationView); } catch (failure) { setError(failure instanceof Error ? failure.message : "Company confirmation failed"); } finally { setBusy(false); } };
  const submitCompany = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(""); try { const result = await api("/api/commerce/draft", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ selection, client: { ...client, registrationCountry: selection.registrationCountry, billingCountry: selection.billingCountry, communicationLanguage: selection.language } }) }); setOrder(result.order as OrderView); setQuote(result.quote as CommerceQuote); setCatalog(result.catalog as CommerceCatalog); setPhase(6); } catch (failure) { setError(failure instanceof Error ? failure.message : "Could not save company data"); } finally { setBusy(false); } };
  const sendOtp = async () => { setBusy(true); setError(""); try { const result = await api("/api/company-verification/email/send", { method: "POST", headers: { "x-csrf-token": csrf }, body: "{}" }); setVerification(result.verification as CompanyVerificationView); setDebugOtp(typeof result.debugCode === "string" ? result.debugCode : ""); } catch (failure) { setError(failure instanceof Error ? failure.message : "Could not send verification code"); } finally { setBusy(false); } };
  const verifyOtp = async () => { setBusy(true); setError(""); try { const result = await api("/api/company-verification/email/verify", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ code: otpCode }) }); setVerification(result.verification as CompanyVerificationView); setOtpCode(""); setDebugOtp(""); } catch (failure) { setError(failure instanceof Error ? failure.message : "Could not verify the code"); } finally { setBusy(false); } };
  const inviteSecondSigner = async () => { setBusy(true); setError(""); setVerificationNotice(""); try { const result = await api("/api/company-verification/second-signer/invite", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify(secondSigner) }); setVerification(result.verification as CompanyVerificationView); setDebugSignerLink(typeof result.debugLink === "string" ? result.debugLink : ""); setVerificationNotice(`${t.inviteSent}${typeof result.debugCode === "string" ? ` ${t.debugOtp}: ${result.debugCode}` : ""}`); } catch (failure) { setError(failure instanceof Error ? failure.message : "Could not invite the second signer"); } finally { setBusy(false); } };
  const uploadPowerOfAttorney = async (file: File | null) => { if (!file) return; setBusy(true); setError(""); try { const response = await fetch("/api/company-verification/power-of-attorney", { method: "POST", credentials: "same-origin", headers: { "x-csrf-token": csrf, "x-file-name": encodeURIComponent(file.name), "content-type": file.type }, body: file }); const result = await response.json() as ApiResult; if (!response.ok || !result.ok) throw new Error(result.message || "Upload failed"); setVerification(result.verification as CompanyVerificationView); setVerificationNotice(t.uploadPending); } catch (failure) { setError(failure instanceof Error ? failure.message : "Upload failed"); } finally { setBusy(false); } };
  const finish = async () => { setBusy(true); setError(""); try { const accepted = await api("/api/commerce/accept", { method: "POST", headers: { "x-csrf-token": csrf }, body: JSON.stringify({ acceptance: { ...acceptance, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone } }) }); setOrder(accepted.order as OrderView); trackEvent("contract_accepted", { market: selection.market, contract_term: selection.contractTerm }); const checkout = await api("/api/commerce/checkout", { method: "POST", headers: { "x-csrf-token": csrf }, body: "{}" }); trackEvent("checkout_started", { market: selection.market, currency: quote?.currency, contract_term: selection.contractTerm }); window.location.assign(checkout.checkoutUrl as string); } catch (failure) { setError(failure instanceof Error ? failure.message : "Checkout could not be started"); } finally { setBusy(false); } };
  const allAccepted = acceptance.companyData && acceptance.agreementAndTerms && acceptance.dataProcessing && acceptance.authority && acceptance.recurringPayment && (selection.contractTerm !== "ANNUAL_12" || acceptance.annualCommitment);
  const officialDataLocked = Boolean(verification && verification.adapter !== "MANUAL");
  const selectedCompanyCountry = companyCountries.find((country) => country.code === selection.registrationCountry) ?? companyCountries[0];
  const companyScopeFields = <div className="verification-card">
    <div className="company-country-lock"><span>{t.companyCountry}</span><b>{selectedCompanyCountry[locale]}</b><small>{selectedCompanyCountry.code} · {selectedCurrency}</small></div>
    {selection.registrationCountry === "PL" ? <label className="contract-field"><span>{t.entityType} *</span><select value={client.entityType} onChange={(event) => selectEntityType(event.target.value as CompanyEntityType)}><option value="PL_KRS">{t.krsEntity}</option><option value="PL_CEIDG">{t.ceidgEntity}</option><option value="OTHER_PL">{t.otherEntity}</option></select></label> : null}
    <div className="contract-grid two">{client.entityType === "PL_KRS" ? <Field label="Numer KRS" name="companyNumber" value={client.companyNumber ?? ""} onChange={setClientField} /> : null}{client.entityType === "PL_CEIDG" ? <Field label="NIP" name="taxId" value={client.taxId} onChange={setClientField} /> : null}{client.entityType === "OTHER_PL" ? <><Field label={t.registryName} name="registryName" value={client.registryName ?? ""} onChange={setClientField} /><Field label={t.fields.companyNumber} name="companyNumber" value={client.companyNumber ?? ""} onChange={setClientField} /></> : null}{client.entityType === "FOREIGN" ? <label className="contract-field"><span>{foreignIdentifier.labels[locale]} *</span><input value={client.companyNumber ?? ""} onChange={(event) => setForeignIdentifier(event.target.value)} /></label> : null}</div>
    {client.entityType === "FOREIGN" ? <small className="registry-source">{t.registryName}: {foreignIdentifier.registryName}</small> : null}
  </div>;

  return <main className="contract-page" lang={locale}><header className="contract-header"><a href={locale === "pl" ? "/pl/" : locale === "es" ? "/es/" : "/"}><img src="/assets/timzy-logo-official-purple.png" width="307" height="158" alt="Timzy" /></a><span>{order?.orderNumber}</span></header><div className="contract-shell"><nav className="contract-progress" aria-label={locale === "pl" ? "Postęp zawierania umowy" : locale === "es" ? "Progreso de contratación" : "Contract progress"}>{processLabels[locale].map((label, index) => index === 1 ? null : <span key={label} aria-current={index === phase ? "step" : undefined} className={index === phase ? "is-current" : index < phase ? "is-complete" : ""}><i>{index < phase ? "✓" : index === 0 ? 1 : index}</i>{label}</span>)}</nav><div className={phase <= 2 ? "contract-workspace contract-workspace--single" : "contract-workspace"}><section className="contract-main"><p className="eyebrow">TIMZY CONTRACT</p><h1>{t.title}</h1><p className="contract-intro">{t.intro}</p>{error ? <div className="contract-error" role="alert">{error}</div> : null}
    {phase === 0 ? <div className="contract-step"><h2>{t.setup}</h2><div className="contract-grid two"><label className="contract-field"><span>{t.companyCountry}</span><select value={selection.registrationCountry} onChange={(event) => selectCompanyCountry(event.target.value)}>{companyCountries.map((country) => <option key={country.code} value={country.code}>{country[locale]}</option>)}</select></label><label className="contract-field"><span>{t.language}</span><select value={locale} onChange={(event) => changeSelection("language", event.target.value as Locale)}><option value="pl">Polski</option><option value="en">English</option><option value="es">Español</option></select></label></div><p className="currency-auto-note">{t.automaticCurrency} <b>{selectedCurrency}</b></p><label className="check-row"><input type="checkbox" checked={marketConfirmed} onChange={(event) => setMarketConfirmed(event.target.checked)} /><span>{t.confirmMarket}<small>{companyCountries.find((country) => country.code === selection.registrationCountry)?.[locale]} · {selectedCurrency}</small></span></label></div> : null}
    {phase === 2 ? <div className="contract-step"><h2>{t.term}</h2><div className="choice-grid"><button type="button" className={selection.contractTerm === "ANNUAL_12" ? "choice-card is-selected" : "choice-card"} onClick={() => changeSelection("contractTerm", "ANNUAL_12")}><b>{t.annual}</b><span>{t.annualText}</span></button><button type="button" className={selection.contractTerm === "OPEN_ENDED" ? "choice-card is-selected" : "choice-card"} onClick={() => changeSelection("contractTerm", "OPEN_ENDED")}><b>{t.open}</b><span>{t.openText}<strong className="choice-fee">+ {wholeMoney(openActivationFeeMinor, selectedCurrency, locale)}</strong></span></button></div></div> : null}
    {phase === 3 ? <div className="contract-step"><h2>{t.plan}</h2>{catalog?.plans.length ? <div className="plan-grid">{catalog.plans.map((plan) => <button type="button" key={plan.id} className={selection.planId === plan.id ? "plan-card is-selected" : "plan-card"} onClick={() => changeSelection("planId", plan.id)}>{plan.recommended ? <em>{t.recommended}</em> : null}<h3>{plan.name}</h3><p>{plan.description}</p><strong>{money(plan.prices.find((price) => price.paymentType === "MONTHLY")?.amountMinor, catalog.market.currency, locale)} / {t.perMonth}</strong><ul>{plan.benefits.map((benefit) => <li key={benefit}>✓ {benefit}</li>)}</ul></button>)}</div> : <div className="configuration-blocker"><b>{t.noOffer}</b><code>{catalog?.blockers.join(" · ")}</code></div>}</div> : null}
    {phase === 4 ? <div className="contract-step"><h2>{t.addons}</h2><div className="addon-list">{catalog?.addons.filter((addon) => selection.planId ? addon.compatiblePlanIds.length === 0 || addon.compatiblePlanIds.includes(selection.planId) : addon.standalone).map((addon) => { const chosen = selection.addons.find((item) => item.addonId === addon.id); const included = Boolean(selectedPlan?.includedAddonIds.includes(addon.id)); return <article key={addon.id} className={chosen || included ? "addon-row is-selected" : "addon-row"}><label><input aria-label={addon.name} type="checkbox" checked={Boolean(chosen || included)} disabled={included} onChange={(event) => toggleAddon(addon.id, event.target.checked)} /><span><b>{addon.name}</b><small>{addon.description}</small></span></label><div>{included ? <em>{t.included}</em> : <><strong>{money(addon.prices[0]?.amountMinor, catalog.market.currency, locale)}</strong>{chosen && addon.maxQuantity > 1 ? <input aria-label={t.quantity} type="number" min={addon.minQuantity} max={addon.maxQuantity} value={chosen.quantity} onChange={(event) => setAddonQuantity(addon.id, Number(event.target.value))} /> : null}</>}</div></article>; })}</div></div> : null}
    {phase === 5 ? <form className="contract-step" onSubmit={submitCompany}><h2>{t.company}</h2>{companyScopeFields}<div className="contract-grid two"><Field label={t.fields.legalName} name="legalName" value={client.legalName} onChange={setClientField} autoComplete="organization" readOnly={officialDataLocked} /><Field label={t.fields.legalForm} name="legalForm" value={client.legalForm} onChange={setClientField} readOnly={officialDataLocked} /><Field label={t.fields.registeredAddress} name="registeredAddress" value={client.registeredAddress} onChange={setClientField} autoComplete="street-address" readOnly={officialDataLocked} /><Field label={t.fields.postalCode} name="postalCode" value={client.postalCode} onChange={setClientField} autoComplete="postal-code" readOnly={officialDataLocked} /><Field label={t.fields.city} name="city" value={client.city} onChange={setClientField} autoComplete="address-level2" readOnly={officialDataLocked} />{client.entityType !== "PL_CEIDG" && !(client.entityType === "FOREIGN" && foreignIdentifier.taxBased) ? <Field label={t.fields.taxId} name="taxId" value={client.taxId} onChange={setClientField} required={selection.registrationCountry === "PL"} readOnly={officialDataLocked} /> : null}</div><button type="button" className="button button--light verification-action" disabled={busy} onClick={() => void lookupCompany()}>{busy ? "…" : t.fetchCompany}</button>{verification ? <div className={`verification-result verification-result--${verification.status.toLowerCase()}`}><b>{t.verificationStatus}: {verificationStatusLabel(verification.status, locale)}</b><span>{verification.verificationSource ?? verification.adapter} · {verification.registryStatus ?? "—"}</span>{verification.representationMethod ? <small>{verification.representationMethod}</small> : null}{verification.reasonDetail ? <small>{verification.reasonDetail}</small> : null}<p>{verification.adapter === "KRS" ? (locale === "pl" ? "Dane pobrane z Krajowego Rejestru Sądowego. Sprawdź ich poprawność przed kontynuowaniem." : t.registryFetched) : t.registryFetched}</p></div> : null}<div className="contract-grid two"><Field label={t.fields.representativeName} name="representativeName" value={client.representativeName} onChange={setClientField} autoComplete="name" /><Field label={t.fields.representativePosition} name="representativePosition" value={client.representativePosition} onChange={setClientField} /><Field label={t.fields.representativeAuthorityBasis} name="representativeAuthorityBasis" value={client.representativeAuthorityBasis} onChange={setClientField} /><Field label={t.fields.businessEmail} name="businessEmail" value={client.businessEmail} onChange={setClientField} type="email" autoComplete="email" /><Field label={t.fields.phone} name="phone" value={client.phone} onChange={setClientField} type="tel" autoComplete="tel" /><Field label={t.fields.brandName} name="brandName" value={client.brandName} onChange={setClientField} /><Field label={t.fields.domain} name="domain" value={client.domain ?? ""} onChange={setClientField} required={false} /><Field label={t.fields.appName} name="appName" value={client.appName} onChange={setClientField} /></div><label className="check-row"><input type="checkbox" checked={client.billingAddressDifferent} onChange={(event) => setClientField("billingAddressDifferent", event.target.checked)} /><span>{t.billingDifferent}</span></label>{client.billingAddressDifferent ? <div className="contract-grid three"><Field label={t.fields.billingAddress} name="billingAddress" value={client.billingAddress ?? ""} onChange={setClientField} /><Field label={t.fields.billingPostalCode} name="billingPostalCode" value={client.billingPostalCode ?? ""} onChange={setClientField} /><Field label={t.fields.billingCity} name="billingCity" value={client.billingCity ?? ""} onChange={setClientField} /></div> : null}<label className="check-row"><input type="checkbox" required checked={client.companyDataConfirmed} onChange={(event) => setClientField("companyDataConfirmed", event.target.checked)} /><span>{t.companyConfirm}</span></label><label className="check-row"><input type="checkbox" required checked={client.authorityConfirmed} onChange={(event) => setClientField("authorityConfirmed", event.target.checked)} /><span>{t.accept3}</span></label><div className="contract-inline-actions"><button type="button" className="button button--light" disabled={busy || !verification || !client.companyDataConfirmed} onClick={() => void confirmVerifiedCompany()}>{t.confirmCompanyButton}</button><button className="button" disabled={busy || !verification?.clientConfirmed}>{busy ? "…" : t.save}</button></div></form> : null}
    {phase === 6 ? <div className="contract-step"><h2>{t.summary}</h2><Summary quote={quote} catalog={catalog} locale={locale} selection={selection} /><div className="summary-lines">{quote?.lines.map((line) => <p key={`${line.itemType}-${line.catalogItemId}-${line.name}`}><span>{line.name} × {line.quantity}{line.included ? ` · ${t.included}` : ""}</span><b>{money(line.totalAmountMinor, quote.currency, locale)}</b></p>)}</div><section className="verification-card"><h3>{t.emailVerification}</h3><p><b>{t.verificationStatus}:</b> {verificationStatusLabel(verification?.status, locale)}</p>{verification?.emailVerified ? <p className="verification-success">✓ {t.emailVerified}</p> : <><button type="button" className="button button--light" disabled={busy} onClick={() => void sendOtp()}>{t.sendCode}</button><div className="otp-row"><label className="contract-field"><span>{t.otp}</span><input inputMode="numeric" maxLength={6} value={otpCode} onChange={(event) => setOtpCode(event.target.value.replace(/\D/g, "").slice(0, 6))} /></label><button type="button" className="button" disabled={busy || otpCode.length !== 6} onClick={() => void verifyOtp()}>{t.verifyCode}</button></div>{debugOtp ? <p className="local-debug-code"><b>{t.debugOtp}:</b> <code>{debugOtp}</code></p> : null}</>}{verification?.status === "SECOND_SIGNER_REQUIRED" ? <div className="verification-subflow"><h3>{t.secondSigner}</h3><div className="contract-grid two"><label className="contract-field"><span>{t.fields.representativeName}</span><input value={secondSigner.name} onChange={(event) => setSecondSigner((current) => ({ ...current, name: event.target.value }))} /></label><label className="contract-field"><span>{t.fields.representativePosition}</span><input value={secondSigner.position} onChange={(event) => setSecondSigner((current) => ({ ...current, position: event.target.value }))} /></label><label className="contract-field"><span>{t.fields.representativeAuthorityBasis}</span><input value={secondSigner.authorityBasis} onChange={(event) => setSecondSigner((current) => ({ ...current, authorityBasis: event.target.value }))} /></label><label className="contract-field"><span>{t.fields.businessEmail}</span><input type="email" value={secondSigner.email} onChange={(event) => setSecondSigner((current) => ({ ...current, email: event.target.value }))} /></label></div><button type="button" className="button button--light" disabled={busy} onClick={() => void inviteSecondSigner()}>{t.sendInvite}</button>{debugSignerLink ? <p className="local-debug-code"><b>Local link:</b> <a href={debugSignerLink} target="_blank" rel="noreferrer">{debugSignerLink}</a></p> : null}</div> : null}{verification?.status === "POWER_OF_ATTORNEY_REQUIRED" ? <div className="verification-subflow"><h3>{t.powerOfAttorney}</h3><label className="contract-field"><span>PDF, JPEG, PNG · max 5 MB</span><input type="file" accept="application/pdf,image/jpeg,image/png" disabled={busy} onChange={(event) => void uploadPowerOfAttorney(event.target.files?.[0] ?? null)} /></label></div> : null}{verificationNotice ? <p className="verification-success">{verificationNotice}</p> : null}{verification?.status !== "VERIFIED" ? <p className="verification-warning">{t.verificationBlocked} {verification?.reasonDetail ?? ""}</p> : null}</section><p className="rollout-note">{t.rollout}</p></div> : null}
    {phase === 7 ? <div className="contract-step"><h2>{t.documents}</h2><div className="document-actions"><a className="button button--light" href="/api/commerce/document-preview?format=html" target="_blank" rel="noreferrer" onClick={() => trackEvent("contract_viewed", { document_format: "html" })}>{t.preview}</a><a className="text-link" href="/api/commerce/document-preview?format=pdf" target="_blank" rel="noreferrer" onClick={() => trackEvent("contract_viewed", { document_format: "pdf" })}>{t.pdf} ↓</a></div><ul className="document-list">{(["AGREEMENT","TERMS","DPA","PRIVACY"] as const).map((kind, index) => <li key={kind}><b>{t.documentNames[index]}</b><span><a href={`/api/commerce/document-preview?format=html&kind=${kind}`} target="_blank" rel="noreferrer">{t.preview}</a><a href={`/api/commerce/document-preview?format=pdf&kind=${kind}`} target="_blank" rel="noreferrer">{t.pdf}</a></span></li>)}</ul><p className="rollout-note">{t.rollout}</p></div> : null}
    {phase === 8 ? <div className="contract-step"><h2>{t.acceptance}</h2><div className="acceptance-party-summary"><h3>{t.company}</h3><p><b>{client.legalName}</b><span>{client.companyNumber || client.taxId} · {client.registeredAddress}, {client.postalCode} {client.city}</span><small>{t.verificationStatus}: {verificationStatusLabel(verification?.status, locale)}</small></p><h3>{t.fields.representativeName}</h3><p><b>{client.representativeName}</b><span>{client.representativePosition} · {client.representativeAuthorityBasis}</span><small>{client.businessEmail} · {verification?.emailVerified ? t.emailVerified : t.verificationBlocked}</small></p></div><div className="acceptance-list">{([['companyData',t.accept0],['authority',t.accept3],['agreementAndTerms',t.accept1],['dataProcessing',t.accept2],['recurringPayment',t.accept5],...(selection.contractTerm === "ANNUAL_12" ? [['annualCommitment',t.accept4]] : [])] as Array<[keyof typeof acceptance,string]>).map(([key,label]) => <label className="check-row" key={key}><input type="checkbox" checked={acceptance[key]} onChange={(event) => setAcceptance((current) => ({ ...current, [key]: event.target.checked }))} /><span>{label}</span></label>)}</div><p className="rollout-note">{t.rollout}</p><button className="button contract-final" disabled={!allAccepted || busy || !quote || !catalog?.checkoutReady || verification?.status !== "VERIFIED"} onClick={() => void finish()}>{busy ? "…" : t.final}</button></div> : null}
    <div className="contract-nav">{phase > 0 ? <button type="button" className="text-link" onClick={() => setPhase((current) => current === 2 ? 0 : current - 1)}>{t.back}</button> : <span />}{phase < 8 && phase !== 5 ? <button type="button" className="button" onClick={next}>{t.next}<span>→</span></button> : null}</div></section>{phase > 2 ? <aside className="contract-aside"><Summary quote={quote} catalog={catalog} locale={locale} selection={selection} /></aside> : null}</div>{phase > 2 ? <details className="mobile-summary"><summary>{t.summary} · {money(quote?.dueTodayNetMinor, quote?.currency ?? catalog?.market.currency ?? "EUR", locale)}</summary><Summary quote={quote} catalog={catalog} locale={locale} selection={selection} /></details> : null}</div></main>;
}
